-- Full re-import of the OurAirports dataset (user-provided CSV), narrowed down
-- from the previous full-world import: worldwide large/medium airports are
-- kept as-is, but small_airport-type entries are now scoped to the US only
-- and require a longest open runway of at least 3000ft (from the
-- companion runways.csv, joined on airports.csv's numeric id ==
-- runways.csv's airport_ref — NOT on ident, since some airports' usable
-- ICAO code lives in gps_code instead, see below). A small_airport with no
-- runway record at all is excluded rather than assumed to qualify.
-- Same ICAO resolution as before: prefer "ident" when it's 4-letter
-- ICAO-shaped, else fall back to "gps_code" (covers cases like
-- Nunapitchuk: ident "16A", real code in gps_code "PPIT").

DELETE FROM "Airport";

